#include "ecu/engine.hpp"
#include <iostream>
#include <stdexcept>
using namespace ecu;static unsigned checks=0;static void ck(bool b,const char*m){++checks;if(!b)throw std::runtime_error(m);}static void near(double a,double b){ck(std::isfinite(a)&&std::abs(a-b)<1e-8,"spark ordering oracle");}
static engine::Inputs in(const engine::Tune&t,bool crank=false){engine::Inputs s;s.rpm=crank?200:2000;s.map_kpa=50;s.tps_pct=10;s.clt_c=85;s.iat_c=25;s.battery_v=14;s.sensor_v=5;s.lambda=1;s.sampled_us=1000000;s.synced=s.phase_synced=s.sensors_valid=true;flex::Capture c(t.flex_fuel.capture);c.edge(920000,true);for(unsigned n=1;n<=8;++n){c.edge(920000+n*10000-3000,false);c.edge(920000+n*10000,true);}s.flex_sample={c.observe(1000000),t.flex_fuel.capture,t.revision};s.table_switches[1]={1000000,secondary::InputSource::Synthetic,true,true};return s;}
int main(){try{for(unsigned mode=0;mode<5;++mode)for(double raw:{-5.,20.,40.})for(double extra:{-40.,-10.,5.,40.})for(double retard:{0.,5.,9.}){
 engine::Tune t;t.strategy=engine::Strategy::Sequential;t.cylinder_trims_enabled=true;t.cylinder_spark_deg={-10,-5,5,10};t.spark.cells.fill(raw);t.afterstart_pct=0;t.dfco_enabled=false;t.warmup_pct.fill(100);t.transient_enrichment.mode=transient::Mode::Off;t.flex_fuel.correction.enabled=true;t.flex_fuel.correction.spark_deg.fill(extra);t.soft_limit_band=500;t.rpm_limit=2500-retard*50;t.rpm_hysteresis=50;auto&r=t.secondary_tables.spark;r.mode=static_cast<secondary::Mode>(mode);r.cells=secondary::expected_cells(r.mode);r.threshold=0;r.debounce_ms=0;t.secondary_spark.cells.fill(mode==1?150:mode==2?7:25);engine::Controller c;auto o=c.step(t,in(t),1000000);ck(!o.faults,"enabled scenario valid");auto combine=[&](double base,double chosen){const double corrected=std::max(-5.,std::clamp(base,-5.,40.)-retard);return mode==1?std::clamp(corrected*1.5,-5.,40.):mode==2?std::clamp(corrected+7,-5.,40.):mode>=3?std::clamp(std::clamp(chosen,-5.,40.)-retard,-5.,40.):corrected;};near(o.advance_deg,combine(raw+extra,25+extra));for(unsigned k=0;k<4;++k)near(o.cylinder_advance_deg[k],combine(raw+t.cylinder_spark_deg[k]+extra,25+t.cylinder_spark_deg[k]+extra));
 engine::Controller cr;const auto crank=cr.step(t,in(t,true),1000000);ck(!crank.faults&&crank.flex_fuel.spark_bypassed&&crank.state==engine::State::Cranking,"crank bypass qualified");near(crank.advance_deg,t.crank_advance_deg);for(unsigned k=0;k<4;++k)near(crank.cylinder_advance_deg[k],std::clamp(double(t.crank_advance_deg+t.cylinder_spark_deg[k]),-5.,15.));
 }
 // Raw samples and strict ETH dependencies retain static qualification even
 // while spark selection is bypassed by cranking or condition is inactive.
 for(bool crank:{false,true})for(bool corrections:{false,true}){engine::Tune t;t.afterstart_pct=0;t.dfco_enabled=false;t.secondary_tables.spark.mode=secondary::Mode::Conditional;t.secondary_tables.spark.condition=secondary::Condition::Ethanol;t.secondary_tables.spark.threshold=99;t.flex_fuel.correction.enabled=corrections;auto s=in(t,crank);s.flex_sample.observation.pending_fault=true;s.flex_sample.observation.fault_generation=1;engine::Controller c;auto o=c.step(t,s,1000000);ck((o.faults&engine::BadSensor)&&o.fuel_cut&&o.spark_cut,"required invalid source inhibits inactive/crank selection");}
 std::cout<<"ordering_adversarial_checks "<<checks<<'\n';return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
